code="import java.sql.*;\npublic class InsertDemo {\n  public static void main(String[] a) throws Exception {\n    // MySQL URL; for Oracle use jdbc:oracle:thin:@localhost:1521:xe\n    try (Connection con = DriverManager.getConnection(\"jdbc:mysql://localhost:3306/college\",\"root\",\"root\");\n         PreparedStatement ps = con.prepareStatement(\"INSERT INTO student(id,name) VALUES(?,?)\")) {\n      ps.setInt(1, 3); ps.setString(2, \"Meena\");\n      System.out.println(ps.executeUpdate() + \" row inserted\");\n    }\n  }\n}",
